#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
using namespace std;

int main() {
    vector<double> notas;
    string t;
    while (true) {
        cout << "Nota (o 'fin'): ";
        cin >> t;
        if (t == "fin") {
            break;
        }
        notas.push_back(stod(t));
    }
    if (notas.size() > 0) {
        double suma = 0;
        for (double n : notas) {
            suma += n;
        }
        cout << fixed << setprecision(1);
        cout << "Promedio: " << suma / notas.size() << endl;
    } else {
        cout << "No cargaste notas" << endl;
    }
    return 0;
}
